add_filter( 'woocommerce_email_order_items_args', 'perfectpixel_product_images_in_emails' );

function perfectpixel_product_images_in_emails( $args ) {
	$size               = max( 24, (int) '{{email_image_size}}' );
	$args['show_image'] = true;
	$args['image_size'] = array( $size, $size );
	return $args;
}
